using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Diagnostics;using System.Threading;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {public static class Stability672Tests {
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}static void Wait(Func<bool> f){var w=Stopwatch.StartNew();while(!f()&&w.Elapsed.TotalSeconds<90){Application.DoEvents();Thread.Sleep(10);}Check(f(),"scene ready");}static void Call(object o,string m){o.GetType().GetMethod(m,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(o,new object[0]);}
 public static int Core(string folder){Directory.CreateDirectory(folder);try{var d=ReferenceRobot67.Cached();var b=RobotCad.Build(d);Check(b.Model.Valid,"current native assembly");var originalPayload=d.Joints.Select(j=>j.Payload).ToArray();foreach(var j in d.Joints)j.Payload=0;foreach(var e in b.Entries.Values)e.MassOverride=0;var moving=b.Entries.Values.Single(e=>e.Id.EndsWith("_tool_jaw_1"));moving.MassOverride=1;foreach(double opening in new[]{0.0,40}){d.GripperOpening=opening;b.InvalidatePose();var result=RobotSolver.Solve(b);var centre=b.Pose(moving.Id,0,false).Transform(RobotBuild.Centre(moving.Part));foreach(var j in d.Joints){var pose=b.Current[j.Id];var force=new Vector3D(0,0,-d.Gravity);double expected=Vector3D.DotProduct(Vector3D.CrossProduct((centre-pose.Origin)/1000,force),pose.Axis);Check(Math.Abs(result.Joints.Single(l=>l.Id==j.Id).SignedEffort-expected)<1e-8,"gripper load follows rendered jaw at "+opening+" / "+j.Id);}}for(int i=0;i<d.Joints.Count;i++)d.Joints[i].Payload=originalPayload[i];var terminal=d.Joints.Last();var adapter=b.Entries[terminal.Id+"_tool_adapter"];var expectedTcp=b.Pose(adapter.Id,0,false).Transform(new Point3D(0,0,64));Check((RobotSolver.LoadPoint(d,terminal,b.Current)-expectedTcp).Length<1e-8,"payload point matches actual flange and fingertip");File.WriteAllText(Path.Combine(folder,"stability672-core-results.txt"),"PASS "+checks+" actual gripper mass/pose/TCP checks.",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"stability672-core-error.txt"),ex.ToString());return 1;}}
 public static int Run(string folder){Directory.CreateDirectory(folder);var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};using(var r=new RobotDesignerForm(Path.Combine(Path.GetDirectoryName(Application.ExecutablePath),"..","examples","Reference67.robot.json")))using(var shell=new WorkspaceShell(r)){var d=r.Document;shell.Show();Wait(()=>r.WebScene.Ready&&r.Scene.Ready);var until=DateTime.UtcNow.AddSeconds(1);Wait(()=>DateTime.UtcNow>until);r.OpenJointControllers();var build=r.Build;var nodes=r.Scene.Nodes.ToArray();int clear=r.WebScene.ClearCount,uploads=r.WebScene.PartUploadCount;int serial=RobotDocument.SerializationCalls;var time=new List<double>();for(int i=0;i<24;i++){var w=Stopwatch.StartNew();r.SetGripperOpening(i%2==0?2:26);time.Add(w.Elapsed.TotalMilliseconds);}Check(RobotDocument.SerializationCalls==serial,"pose edits serialize no embedded CAD project");Check(r.HistoryBytes<32000,"24 pose history entries are compact");Check(ReferenceEquals(build,r.Build)&&nodes.SequenceEqual(r.Scene.Nodes),"pose edits preserve assembly and meshes");Check(clear==r.WebScene.ClearCount&&uploads==r.WebScene.PartUploadCount,"pose edits send no geometry");for(int i=0;i<24;i++)Call(r,"Undo");Check(d.GripperOpening==20,"undo restores exact initial opening");for(int i=0;i<24;i++)Call(r,"Redo");Check(d.GripperOpening==26,"redo restores final opening");Check(RobotDocument.SerializationCalls==serial,"undo redo serialize no embedded CAD");int count=r.UndoCount;r.SetGripperOpening(26);Check(r.UndoCount==count,"no-op adds no history");var grip=d.GripperOpening;r.JogJoint(d.Joints[1].Id,5);Call(r,"Undo");Check(d.GripperOpening==grip&&d.Joints[1].Position==-10,"joint undo preserves gripper");time.Sort();File.WriteAllText(Path.Combine(folder,"stability672-performance-results.json"),CADDocument.Serializer().Serialize(new{Version=ReleaseSupport.Version,MedianGripperMs=time[time.Count/2],P95GripperMs=time[(int)(time.Count*.95)],PoseProjectSerializations=RobotDocument.SerializationCalls-serial,HistoryBytes=r.HistoryBytes,Checks=checks}),Encoding.UTF8);Call(r,"TogglePlay");Call(r,"Undo");Check(!(bool)typeof(RobotDesignerForm).GetField("playing",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(r),"undo stops active animation");double restoredOpening=r.Document.GripperOpening;var settled=DateTime.UtcNow.AddMilliseconds(150);Wait(()=>DateTime.UtcNow>settled);Check(r.Document.GripperOpening==restoredOpening,"undo state survives subsequent timer ticks");Call(r,"Redo");for(int i=0;i<24;i++)Call(r,"Undo");Check(!r.Text.EndsWith(" *"),"undo all poses clears saved-state marker");r.JogJoint(d.Joints[1].Id,5);var name=d.Joints[1].Name;d.Joints[1].Name=name+" renamed";typeof(RobotDesignerForm).GetMethod("PropertyChanged",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(r,new object[]{"Name",System.ComponentModel.TypeDescriptor.GetProperties(d.Joints[1])["Name"],name});Wait(()=>r.Scene.Ready);Call(r,"Undo");Wait(()=>r.Scene.Ready);Call(r,"Undo");Check(!r.Text.EndsWith(" *")&&r.Document.Joints[1].Name==name&&r.Document.Joints[1].Position==-10,"mixed structural and pose undo restores saved state");var legacy=RobotDocument.Example();legacy.Joints[0].Position=45;r.SetDocument(legacy);Wait(()=>r.Scene.Ready);r.SetStage(0);AppSettings.Current.SnapEnabled=true;AppSettings.Current.SnapStep=10;string guide=legacy.Joints[0].Id+"_end_guide";var originalTip=r.Build.Current[legacy.Joints[0].Id].Tip;typeof(RobotDesignerForm).GetMethod("CommitWebDrag",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(r,new object[]{guide,new Vector3D(40,0,0)});Check((r.Build.Current[legacy.Joints[0].Id].Tip-originalTip-new Vector3D(40,0,0)).Length<1e-6,"world-snapped drag is not rounded again in rotated local coordinates");shell.ApproveTestClose();shell.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"stability672-error.txt"),ex.ToString());return 1;}finally{AppSettings.Current=old;}}
}}
